const cloud = require('wx-server-sdk')

cloud.init({
  env: 'cloud1-d4gc2e7w9638ce590',
  traceUser: false
})

const db = cloud.database()

// Generated by scripts/sync-cloudfunctions.mjs from the app's local catalog.
// The deployed copy is authoritative for product prices.
let catalog = { products: [] }
try {
  catalog = require('./catalog.json')
} catch (error) {
  console.warn('Product catalog missing; direct orders will be rejected')
}

const findProduct = (productId) =>
  (catalog.products || []).find((product) => product.id === productId)

const toMoney = (value) => Math.round(Number(value) * 100) / 100

exports.main = async (event, context) => {
  const { items, discount = 0, order: orderData } = event
  const { OPENID } = cloud.getWXContext()

  try {
    if (orderData && typeof orderData === 'object') {
      const quantity = Number(orderData.quantity || 1)
      if (!Number.isInteger(quantity) || quantity <= 0) {
        return { success: false, error: 'Order quantity is invalid' }
      }

      const product = findProduct(orderData.productId)
      if (!product || (product.status && product.status !== 'published')) {
        return { success: false, error: 'Unknown or unavailable product' }
      }

      const expectedTotal = toMoney(product.price * quantity)
      if (toMoney(orderData.totalPrice) !== expectedTotal) {
        return { success: false, error: 'Order total does not match the product catalog' }
      }

      const order = {
        ...orderData,
        userId: OPENID,
        enabled: true,
        status: 'LOCKED',
        quantity,
        totalPrice: expectedTotal,
        productSnapshot: {
          ...(orderData.productSnapshot || {}),
          productId: product.id,
          title: product.title || orderData.productSnapshot?.title || '',
          price: product.price
        },
        payment: {
          method: 'wechat',
          status: 'pending',
          transactionId: null,
          paidAt: null
        },
        createdAt: db.serverDate(),
        updatedAt: db.serverDate()
      }

      delete order.id
      delete order._id

      const result = await db.collection('xingqiba_orders').add({
        data: order
      })

      return {
        success: true,
        orderId: result._id,
        order: {
          ...order,
          _id: result._id
        }
      }
    }

    if (!Array.isArray(items) || items.length === 0) {
      return { success: false, error: 'Order items required' }
    }

    const validatedItems = []
    for (const item of items) {
      const quantity = Number(item.quantity || 1)
      if (!Number.isInteger(quantity) || quantity <= 0) {
        return { success: false, error: 'Order quantity is invalid' }
      }

      const product = findProduct(item.productId)
      if (!product || (product.status && product.status !== 'published')) {
        return { success: false, error: `Unknown or unavailable product: ${item.productId || 'missing id'}` }
      }

      if (toMoney(item.price) !== toMoney(product.price)) {
        return { success: false, error: `Price mismatch for product: ${product.id}` }
      }

      validatedItems.push({
        ...item,
        title: product.title || item.title,
        price: product.price,
        quantity
      })
    }

    const subtotal = toMoney(
      validatedItems.reduce((sum, item) => sum + item.price * item.quantity, 0)
    )
    const finalTotal = toMoney(subtotal - Number(discount || 0))
    if (finalTotal <= 0) {
      return { success: false, error: 'Order total is invalid' }
    }

    const order = {
      userId: OPENID,
      items: validatedItems,
      subtotal,
      discount: Number(discount || 0),
      total: finalTotal,
      payment: {
        method: 'wechat',
        status: 'pending',
        transactionId: null,
        paidAt: null
      },
      createdAt: db.serverDate(),
      updatedAt: db.serverDate()
    }

    const result = await db.collection('xingqiba_orders').add({
      data: order
    })

    return {
      success: true,
      orderId: result._id,
      order: {
        ...order,
        _id: result._id
      }
    }
  } catch (error) {
    console.error('Create order error:', error)
    return {
      success: false,
      error: error.message
    }
  }
}
